//! The Wiener first-passage time distribution: 50-digit reference values (`fixtures/wiener.json`, generated by
//! `fixtures/wiener.py` with mpmath), the density integrated over time against the boundary probabilities, the
//! derivatives against finite differences in both series' regimes, and the samplers.

mod common;

use common::s;
use keanu_distributions::{KeanuRng, Wiener, sample_wiener};
use keanu_tensor::{DoubleTensor, IntTensor};
use serde_json::Value;

const T0: f64 = 0.2;

/// The log density of one response time.
fn log_p(x: f64, [a, t0, w, v, sv]: [f64; 5], boundary: i64) -> f64 {
    Wiener::log_prob_and_gradient(x, [a, t0, w, v, sv], boundary).0
}

#[test]
fn log_density_matches_the_reference_values() {
    let fixture: Value = serde_json::from_str(include_str!("fixtures/wiener.json")).unwrap();
    let cases = fixture.as_array().unwrap();
    assert!(cases.len() > 1500);
    let mut worst: f64 = 0.0;
    for case in cases {
        let get = |name: &str| case[name].as_f64().unwrap();
        let p = [get("a"), get("t0"), get("w"), get("v"), get("sv")];
        let (x, boundary) = (get("x"), case["boundary"].as_i64().unwrap());
        let expected = get("log_p");
        let actual = log_p(x, p, boundary);
        // the value from the jets (the tensor API's path) is the same formula
        let tensor = Wiener::new(
            s(p[0]),
            s(p[1]),
            s(p[2]),
            s(p[3]),
            s(p[4]),
            IntTensor::scalar(boundary),
        )
        .log_prob(&s(x))
        .unwrap()
        .as_slice()[0];
        let error = (actual - expected).abs() / expected.abs().max(1.0);
        let jet_error = (tensor - expected).abs() / expected.abs().max(1.0);
        worst = worst.max(error).max(jet_error);
        assert!(
            error < 1e-13 && jet_error < 1e-13,
            "x = {x}, {p:?}, boundary {boundary}: {actual} (jets {tensor}), expected {expected}"
        );
    }
    eprintln!("largest relative error of the log density: {worst:e}");
}

// ----- quadrature -----

/// ∫ f over (a, b) by tanh-sinh quadrature, an infinite upper end mapped to a finite one.
fn integrate(f: impl Fn(f64) -> f64, a: f64, b: f64) -> f64 {
    if b.is_finite() {
        tanh_sinh(f, a, b)
    } else {
        tanh_sinh(|u| f(a + u / (1.0 - u)) / ((1.0 - u) * (1.0 - u)), 0.0, 1.0)
    }
}

fn tanh_sinh(f: impl Fn(f64) -> f64, a: f64, b: f64) -> f64 {
    let (c, d) = (0.5 * (a + b), 0.5 * (b - a));
    let h = 1.0 / 64.0;
    let half_pi = std::f64::consts::FRAC_PI_2;
    let mut total = 0.0;
    for k in -256..=256 {
        let t = k as f64 * h;
        let u = half_pi * t.sinh();
        let x = u.tanh();
        let weight = half_pi * t.cosh() / (u.cosh() * u.cosh());
        let point = c + d * x;
        if point <= a || point >= b {
            continue;
        }
        let value = f(point);
        if value.is_finite() {
            total += weight * value;
        }
    }
    total * d * h
}

/// The probability that the process ends at the upper boundary given the drift: (1 − e^{−2vaw})/(1 − e^{−2va}).
fn upper_given_drift(a: f64, w: f64, v: f64) -> f64 {
    if v == 0.0 {
        w
    } else {
        (-2.0 * v * a * w).exp_m1() / (-2.0 * v * a).exp_m1()
    }
}

/// The probability of the upper boundary, averaged over the drift's N(v, sv²) by quadrature when sv > 0.
fn upper_probability(a: f64, w: f64, v: f64, sv: f64) -> f64 {
    if sv == 0.0 {
        return upper_given_drift(a, w, v);
    }
    let normal = |z: f64| (-0.5 * z * z).exp() / (2.0 * std::f64::consts::PI).sqrt();
    integrate(
        |z| upper_given_drift(a, w, v + sv * z) * normal(z),
        -12.0,
        12.0,
    )
}

/// ∫ p(t, boundary) dt over (t0, x): the probability of ending at the boundary by time x.
fn mass(p: [f64; 5], boundary: i64, x: f64) -> f64 {
    let t0 = p[1];
    // the density is concentrated within a few multiples of a² after t0: split there for the quadrature
    let knee = t0 + p[0] * p[0];
    let density = |t: f64| log_p(t, p, boundary).exp();
    if x <= knee {
        integrate(density, t0, x)
    } else {
        integrate(density, t0, knee) + integrate(density, knee, x)
    }
}

const PARAMETER_SETS: [[f64; 5]; 8] = [
    [1.0, T0, 0.5, 0.0, 0.0],
    [1.5, T0, 0.3, 1.2, 0.0],
    [0.8, 0.0, 0.7, -2.0, 0.0],
    [2.5, T0, 0.5, 0.4, 0.0],
    [1.2, T0, 0.1, 3.0, 0.0],
    [1.0, T0, 0.5, 0.8, 1.0],
    [2.0, 0.3, 0.35, -0.6, 0.5],
    [0.7, T0, 0.85, 1.5, 2.0],
];

#[test]
fn the_density_integrates_to_the_boundary_probabilities() {
    for p in PARAMETER_SETS {
        let upper = upper_probability(p[0], p[2], p[3], p[4]);
        let lower_mass = mass(p, 0, f64::INFINITY);
        let upper_mass = mass(p, 1, f64::INFINITY);
        assert!(
            (upper_mass - upper).abs() < 1e-6 && (lower_mass - (1.0 - upper)).abs() < 1e-6,
            "{p:?}: masses {lower_mass} and {upper_mass}, upper probability {upper}"
        );
    }
}

/// Checks the hand gradient against the jets' and both against central differences, and the jets' Hessian against
/// central differences of the gradient.
fn check_derivatives(x: f64, p: [f64; 5], boundary: i64) {
    let what = format!("x = {x}, {p:?}, boundary {boundary}");
    let mut inputs = vec![x];
    inputs.extend_from_slice(&p);
    let split = |inputs: &[f64]| (inputs[0], std::array::from_fn(|i| inputs[i + 1]));
    let (value, gradient) = Wiener::log_prob_and_gradient(x, p, boundary);
    let jets = Wiener::log_prob_derivatives(x, p, boundary);
    assert!(
        (jets.value - value).abs() < 1e-12 * value.abs().max(1.0),
        "{what}: values"
    );
    for i in 0..6 {
        assert!(
            (jets.gradient[i] - gradient[i]).abs() < 1e-10 * gradient[i].abs().max(1.0),
            "{what}: d/d input {i} = {} by hand, {} by jets",
            gradient[i],
            jets.gradient[i]
        );
        let h = 1e-5 * inputs[i].abs().max(0.1);
        let mut plus = inputs.clone();
        let mut minus = inputs.clone();
        plus[i] += h;
        minus[i] -= h;
        let (xp, pp) = split(&plus);
        let (xm, pm) = split(&minus);
        let (vp, gp) = Wiener::log_prob_and_gradient(xp, pp, boundary);
        let (vm, gm) = Wiener::log_prob_and_gradient(xm, pm, boundary);
        // at t0 = 0 or sv = 0, where the parameter can't decrease, a second-order one-sided difference
        let one_sided = vm.is_nan();
        let (v2, g2) = if one_sided {
            plus[i] += h;
            let (x2, p2) = split(&plus);
            Wiener::log_prob_and_gradient(x2, p2, boundary)
        } else {
            (vm, gm)
        };
        let difference = |at: f64, plus: f64, minus: f64, twice: f64| {
            if one_sided {
                (-3.0 * at + 4.0 * plus - twice) / (2.0 * h)
            } else {
                (plus - minus) / (2.0 * h)
            }
        };
        let numeric = difference(value, vp, vm, v2);
        assert!(
            (gradient[i] - numeric).abs() < 1e-6 * numeric.abs().max(1.0),
            "{what}: d/d input {i} = {}, finite difference {numeric}",
            gradient[i]
        );
        for j in 0..6 {
            let numeric = difference(gradient[j], gp[j], gm[j], g2[j]);
            assert!(
                (jets.hessian[i][j] - numeric).abs() < 1e-5 * numeric.abs().max(1.0),
                "{what}: d²/d input {i} d input {j} = {}, finite difference {numeric}",
                jets.hessian[i][j]
            );
        }
    }
}

#[test]
fn derivatives_match_finite_differences_at_small_and_large_times() {
    for p in PARAMETER_SETS {
        // decision times from a hundredth of a² (the small-time series) to six times a² (the large-time one)
        for scaled in [0.02, 0.1, 0.3, 0.6, 1.5, 6.0] {
            let x = p[1] + scaled * p[0] * p[0];
            for boundary in [0, 1] {
                check_derivatives(x, p, boundary);
            }
        }
    }
}

#[test]
fn invalid_parameters_and_times_before_t0() {
    let good = [1.0, T0, 0.5, 0.3, 0.2];
    assert_eq!(log_p(T0, good, 0), f64::NEG_INFINITY);
    assert_eq!(log_p(0.1, good, 1), f64::NEG_INFINITY);
    for bad in [
        [0.0, T0, 0.5, 0.3, 0.2],
        [1.0, -0.1, 0.5, 0.3, 0.2],
        [1.0, T0, 0.0, 0.3, 0.2],
        [1.0, T0, 1.0, 0.3, 0.2],
        [1.0, T0, 0.5, f64::INFINITY, 0.2],
        [1.0, T0, 0.5, 0.3, -0.2],
    ] {
        assert!(log_p(1.0, bad, 0).is_nan(), "{bad:?}");
        let d = Wiener::new(
            s(bad[0]),
            s(bad[1]),
            s(bad[2]),
            s(bad[3]),
            s(bad[4]),
            IntTensor::scalar(0),
        );
        assert!(
            d.sample(&[1], &mut KeanuRng::seed_from_u64(1)).is_err(),
            "{bad:?}"
        );
    }
    assert!(log_p(1.0, good, 2).is_nan());
    let d = Wiener::new(s(1.0), s(T0), s(0.5), s(0.3), s(0.2), IntTensor::scalar(-1));
    assert!(d.sample(&[1], &mut KeanuRng::seed_from_u64(1)).is_err());
}

#[test]
fn parameters_broadcast_with_the_value() {
    let boundary = IntTensor::vector(vec![0, 1, 1]);
    let d = Wiener::new(
        s(1.2),
        s(T0),
        DoubleTensor::vector(vec![0.3, 0.5, 0.6]),
        s(0.8),
        s(0.0),
        &boundary,
    );
    let x = DoubleTensor::vector(vec![0.5, 0.9, 1.4]);
    let lp = d.log_prob(&x).unwrap();
    let g = d.d_log_prob(&x).unwrap();
    for i in 0..3 {
        let p = [1.2, T0, [0.3, 0.5, 0.6][i], 0.8, 0.0];
        let b = boundary.as_slice()[i];
        let (value, gradient) = Wiener::log_prob_and_gradient(x.as_slice()[i], p, b);
        assert_eq!(lp.as_slice()[i], value);
        assert_eq!(g.x.as_slice()[i], gradient[0]);
        assert_eq!(g.a.as_slice()[i], gradient[1]);
        assert_eq!(g.t0.as_slice()[i], gradient[2]);
        assert_eq!(g.w.as_slice()[i], gradient[3]);
        assert_eq!(g.v.as_slice()[i], gradient[4]);
        assert_eq!(g.sv.as_slice()[i], gradient[5]);
    }
    assert_eq!(
        d.sample(&[2, 3], &mut KeanuRng::seed_from_u64(3))
            .unwrap()
            .shape(),
        &[2, 3]
    );
}

/// The Kolmogorov–Smirnov statistic of sorted draws against a CDF, at 200 evenly spaced order statistics.
fn ks_statistic(draws: &mut [f64], cdf: impl Fn(f64) -> f64) -> f64 {
    draws.sort_by(f64::total_cmp);
    let n = draws.len();
    (0..n)
        .step_by(n / 200)
        .map(|k| {
            let c = cdf(draws[k]);
            (c - k as f64 / n as f64)
                .abs()
                .max((c - (k + 1) as f64 / n as f64).abs())
        })
        .fold(0.0, f64::max)
}

#[test]
fn joint_draws_match_the_boundary_probabilities_and_the_density() {
    let n = 20_000;
    for (i, p) in PARAMETER_SETS.iter().enumerate() {
        let mut rng = KeanuRng::seed_from_u64(40 + i as u64);
        let (times, boundaries) = sample_wiener(
            &s(p[0]),
            &s(p[1]),
            &s(p[2]),
            &s(p[3]),
            &s(p[4]),
            &[n],
            &mut rng,
        )
        .unwrap();
        let upper = upper_probability(p[0], p[2], p[3], p[4]);
        let count = boundaries.as_slice().iter().filter(|&&b| b == 1).count() as f64;
        let sd = (upper * (1.0 - upper) / n as f64).sqrt();
        assert!(
            (count / n as f64 - upper).abs() < 4.0 * sd + 1e-9,
            "{p:?}: upper share {}, probability {upper}",
            count / n as f64
        );
        for boundary in [0, 1] {
            let mut draws: Vec<f64> = times
                .as_slice()
                .iter()
                .zip(boundaries.as_slice())
                .filter(|&(_, &b)| b == boundary)
                .map(|(&t, _)| t)
                .collect();
            if draws.len() < 1000 {
                continue;
            }
            assert!(draws.iter().all(|&t| t > p[1]));
            let total = mass(*p, boundary, f64::INFINITY);
            let m = draws.len();
            let statistic = ks_statistic(&mut draws, |x| mass(*p, boundary, x) / total);
            assert!(
                statistic < 1.95 / (m as f64).sqrt(),
                "{p:?}, boundary {boundary}: KS statistic {statistic} over {m} draws"
            );
        }
    }
}

#[test]
fn conditional_draws_match_the_density_at_their_boundary() {
    let n = 10_000;
    for (i, p) in PARAMETER_SETS.iter().enumerate() {
        for boundary in [0, 1] {
            let d = Wiener::new(
                s(p[0]),
                s(p[1]),
                s(p[2]),
                s(p[3]),
                s(p[4]),
                IntTensor::scalar(boundary),
            );
            let mut rng = KeanuRng::seed_from_u64(70 + 2 * i as u64 + boundary as u64);
            let mut draws = d.sample(&[n], &mut rng).unwrap().into_vec();
            let total = mass(*p, boundary, f64::INFINITY);
            let statistic = ks_statistic(&mut draws, |x| mass(*p, boundary, x) / total);
            assert!(
                statistic < 1.95 / (n as f64).sqrt(),
                "{p:?}, boundary {boundary}: KS statistic {statistic}"
            );
        }
    }
}
